const inputs=$input.all().map(item=>item.json??{});
if(inputs.length!==1){
  throw new Error('O Publisher aceita exatamente uma publicação por execução para garantir um único commit.');
}
const publication=inputs[0];
const owner=String(publication.owner??'').trim();
const repository=String(publication.repository??'').trim();
const branch=String(publication.branch??'').trim();
if(!owner||!repository||!branch) throw new Error('owner, repository e branch são obrigatórios.');
if(branch.startsWith('refs/')||branch.startsWith('/')||branch.endsWith('/')||branch.includes('..')){
  throw new Error('Nome de branch inválido: '+branch);
}
const entries=Array.isArray(publication.files)
  ? publication.files.map(file=>[file.path,file.content])
  : Object.entries(publication.files??{});
const deletePaths=Array.isArray(publication.deletePaths)?publication.deletePaths.map(String):[];
if(entries.length===0&&deletePaths.length===0) throw new Error('Nenhum arquivo ou remoção recebido para publicação.');
const paths=new Set();
const treeEntries=[];
for(const [pathValue,contentValue] of entries){
  const filePath=String(pathValue??'').replace(/^\/+/, '');
  const invalidSegment=filePath.split('/').some(segment=>!segment||segment==='.'||segment==='..');
  if(!filePath.startsWith('projects/')||invalidSegment){
    throw new Error('Caminho de publicação inválido: '+filePath);
  }
  if(paths.has(filePath)) throw new Error('Caminho duplicado no mesmo commit: '+filePath);
  if(typeof contentValue!=='string') throw new Error('Conteúdo deve ser texto: '+filePath);
  paths.add(filePath);
  treeEntries.push({path:filePath,mode:'100644',type:'blob',content:contentValue});
}
for(const pathValue of deletePaths){
  const filePath=String(pathValue??'').replace(/^\/+/, '');
  if(filePath!=='PR_REVIEW.md'){
    throw new Error('Remoção não permitida: '+filePath+'. Somente o PR_REVIEW.md legado pode ser removido.');
  }
  if(paths.has(filePath)) throw new Error('Caminho duplicado no mesmo commit: '+filePath);
  paths.add(filePath);
  treeEntries.push({path:filePath,mode:'100644',type:'blob',sha:null});
}
treeEntries.sort((a,b)=>a.path.localeCompare(b.path));
return [{json:{
  owner,
  repository,
  branch,
  projectSlug:String(publication.projectSlug??'').trim(),
  commitMessage:String(publication.commitMessage??('docs('+publication.projectSlug+'): atomic publication')),
  fileCount:treeEntries.length,
  deleteCount:deletePaths.length,
  deletePaths,
  paths:treeEntries.map(entry=>entry.path),
  treeEntries
}}];

const publication=$('Preparar commit atômico').first().json;
const baseCommitSha=String($json.object?.sha??'');
if(!/^[a-f0-9]{40}$/i.test(baseCommitSha)){
  throw new Error('A referência da branch não retornou um commit SHA válido.');
}
return [{json:{...publication,baseCommitSha}}];

const publication=$('Preparar consulta do commit base').first().json;
const baseTreeSha=String($json.tree?.sha??'');
if(!/^[a-f0-9]{40}$/i.test(baseTreeSha)){
  throw new Error('O commit base não retornou uma tree SHA válida.');
}
return [{json:{
  ...publication,
  baseTreeSha,
  treeRequestBody:{
    base_tree:baseTreeSha,
    tree:publication.treeEntries
  }
}}];

const context=$('Preparar nova árvore').first().json;
const newTreeSha=String($json.sha??'');
if(!/^[a-f0-9]{40}$/i.test(newTreeSha)){
  throw new Error('A nova árvore não retornou um SHA válido.');
}
return [{json:{
  ...context,
  newTreeSha,
  commitRequestBody:{
    message:context.commitMessage,
    tree:newTreeSha,
    parents:[context.baseCommitSha]
  }
}}];

const context=$('Preparar commit único').first().json;
const newCommitSha=String($json.sha??'');
if(!/^[a-f0-9]{40}$/i.test(newCommitSha)){
  throw new Error('O novo commit não retornou um SHA válido.');
}
return [{json:{
  ...context,
  newCommitSha,
  refRequestBody:{sha:newCommitSha,force:false}
}}];

const context=$('Preparar atualização da referência').first().json;
const publishedSha=String($json.object?.sha??context.newCommitSha);
if(publishedSha!==context.newCommitSha){
  throw new Error('A branch não aponta para o commit recém-criado.');
}
return [{json:{
  action:'committed',
  changed:true,
  atomic:true,
  owner:context.owner,
  repository:context.repository,
  branch:context.branch,
  projectSlug:context.projectSlug,
  previousCommitSha:context.baseCommitSha,
  commitSha:context.newCommitSha,
  treeSha:context.newTreeSha,
  commitMessage:context.commitMessage,
  fileCount:context.fileCount,
  paths:context.paths
}}];
